public sealed class PayrollServiceTests
{
    [Fact]
    public void CalculateTotalHours_WhenCompletedEntriesExist_ReturnsTheirTotal()
    {
        var repository = new ClockEntryRepository();
        var service = new PayrollService(repository);
        var start = new DateTime(2026, 8, 13, 9, 0, 0);
        var firstEntry = new ClockEntry(1, start);
        var secondEntry = new ClockEntry(1, start.AddDays(1));

        firstEntry.ClockOutEntry(start.AddHours(3));
        secondEntry.ClockOutEntry(start.AddDays(1).AddHours(4));
        repository.SaveClockEntry(firstEntry);
        repository.SaveClockEntry(secondEntry);

        double total = service.CalculateTotalHours(1, start.Date, start.Date.AddDays(2));

        Assert.Equal(7, total);
    }

    [Fact]
    public void CalculateTotalHours_WhenNoEntriesExist_ReturnsZero()
    {
        var repository = new ClockEntryRepository();
        var service = new PayrollService(repository);

        double total = service.CalculateTotalHours(
            1,
            new DateTime(2026, 8, 13),
            new DateTime(2026, 8, 14));

        Assert.Equal(0, total);
    }
}
